SELECT DISTINCT G.NUNOTA AS "Numero Unico",                 G.NUMNOTA AS "Numero Nota",                 DATE_FORMAT(G.DATA_ENTREGA, '%d/%m/%Y') AS "Data Entrega",                 SUM(I.PESO_ITEM) AS "Peso Bruto (Kg)",                 SUM(I.PESO_ITEM_LIQ) AS "Peso Liquido (Kg)" FROM   (SELECT *    FROM GESTAO_NOTAS_APROVACAO    ) G JOIN IMP_ITENS_NOTAS_APRV I ON G.NUNOTA = I.NUNOTA WHERE G.CODPARC = :VAR_PARCEIRO_SELECIONADO   AND G.DATA_ENTREGA BETWEEN :VAR_PERIODO_INICIO AND :VAR_PERIODO_FIM   AND G.ENTREGUE = 1 GROUP BY G.NUNOTA,          G.NUMNOTA,          G.DATA_ENTREGA ORDER BY G.DATA_ENTREGA,          G.NUNOTA